@testable import FarolCore

/// Lines shaped like Claude Code's own log, with only the fields Transcript reads and some it must skip.
private let log = [
    #"{"type":"permission-mode","permissionMode":"default"}"#,
    #"{"parentUuid":null,"type":"user","uuid":"u1","cwd":"/Users/me/shelf","message":{"role":"user","content":"the order test fails one run in ten"}}"#,
    #"{"parentUuid":"u1","type":"user","uuid":"u2","isMeta":true,"message":{"role":"user","content":"Caveat: the messages below were generated by the user"}}"#,
    #"{"parentUuid":"u2","type":"user","uuid":"u3","message":{"role":"user","content":"<command-name>/clear</command-name>"}}"#,
    #"{"parentUuid":"u3","type":"assistant","uuid":"a1","cwd":"/Users/me/shelf","message":{"role":"assistant","content":[{"type":"thinking","thinking":"hmm"},{"type":"text","text":"The test compares two links saved in the same millisecond."}]}}"#,
    #"{"parentUuid":"a1","type":"assistant","uuid":"a2","cwd":"/Users/me/shelf","message":{"role":"assistant","content":[{"type":"tool_use","name":"Bash","input":{"command":"npm test","description":"Run the tests"}}]}}"#,
    #"{"parentUuid":"a2","type":"user","uuid":"u4","message":{"role":"user","content":[{"type":"tool_result","content":"12 passed"}]}}"#,
    #"{"parentUuid":"u4","type":"assistant","uuid":"a3","cwd":"/Users/me/shelf","message":{"role":"assistant","content":[{"type":"tool_use","name":"Edit","input":{"file_path":"/Users/me/shelf/tests/store.test.ts","old_string":"await sleep(1)","new_string":"const clock = fixedClock()\nconst store = createStore({ clock })"}}]}}"#,
    #"{"parentUuid":"a3","type":"assistant","uuid":"a4","isSidechain":true,"message":{"role":"assistant","content":[{"type":"text","text":"from a subagent"}]}}"#,
    #"{"type":"api-request","payload":"{\"type\":\"user\"}"}"#,
    "not json at all",
]

private func file(_ lines: [String]) throws -> URL {
    let url = FileManager.default.temporaryDirectory.appendingPathComponent("transcript-\(UUID().uuidString).jsonl")
    try (lines.joined(separator: "\n") + "\n").write(to: url, atomically: true, encoding: .utf8)
    return url
}

@Test func readsTheConversationAndSkipsTheRest() throws {
    let transcript = Transcript(url: try file(log))
    #expect(transcript.refresh())
    let messages = transcript.messages
    #expect(messages.map(\.role) == [.you, .agent, .tool, .tool])
    #expect(messages[0].text == "the order test fails one run in ten")
    #expect(messages[1].text == "The test compares two links saved in the same millisecond.")
    #expect(messages[2].text == "Run the tests" && messages[2].tool == "Bash" && messages[2].detail == "npm test")
    #expect(messages[3].text == "tests/store.test.ts")
    #expect(messages[3].detail == "@@\n-await sleep(1)\n+const clock = fixedClock()\n+const store = createStore({ clock })\n")
}

@Test func readsOnlyWhatWasAdded() throws {
    let url = try file(Array(log.prefix(2)))
    let transcript = Transcript(url: url)
    #expect(transcript.refresh())
    #expect(transcript.messages.count == 1)
    #expect(!transcript.refresh())

    // Half a line, as an agent that is still writing leaves it, then the rest.
    let handle = try FileHandle(forWritingTo: url)
    try handle.seekToEnd()
    let line = Data((log[4] + "\n").utf8)
    try handle.write(contentsOf: line.prefix(40))
    #expect(!transcript.refresh())
    try handle.write(contentsOf: line.dropFirst(40))
    try handle.close()
    #expect(transcript.refresh())
    #expect(transcript.messages.map(\.role) == [.you, .agent])
}

@Test func startsOverWhenTheLogIsRewritten() throws {
    let url = try file(log)
    let transcript = Transcript(url: url)
    transcript.refresh()
    try (log[1] + "\n").write(to: url, atomically: true, encoding: .utf8)
    #expect(transcript.refresh())
    #expect(transcript.messages.count == 1)
}

@Test func leavesOutWhatARewindReplaced() throws {
    let transcript = Transcript(url: try file([
        #"{"parentUuid":null,"type":"user","uuid":"p1","message":{"role":"user","content":"read the store"}}"#,
        // Two reads side by side, each answered under its own call.
        #"{"parentUuid":"p1","type":"assistant","uuid":"r1","message":{"role":"assistant","content":[{"type":"tool_use","name":"Read","input":{"file_path":"/a.ts"}}]}}"#,
        #"{"parentUuid":"r1","type":"assistant","uuid":"r2","message":{"role":"assistant","content":[{"type":"tool_use","name":"Read","input":{"file_path":"/b.ts"}}]}}"#,
        #"{"parentUuid":"r2","type":"user","uuid":"t2","message":{"role":"user","content":[{"type":"tool_result","content":"b"}]}}"#,
        #"{"parentUuid":"r1","type":"user","uuid":"t1","message":{"role":"user","content":[{"type":"tool_result","content":"a"}]}}"#,
        #"{"parentUuid":"t2","type":"assistant","uuid":"a1","message":{"role":"assistant","content":[{"type":"text","text":"Both read."}]}}"#,
        #"{"parentUuid":"a1","type":"user","uuid":"p2","message":{"role":"user","content":"delete them"}}"#,
        #"{"parentUuid":"p2","type":"assistant","uuid":"a2","message":{"role":"assistant","content":[{"type":"text","text":"Deleted."}]}}"#,
        // You rewound to before "delete them" and asked something else.
        #"{"parentUuid":"a1","type":"user","uuid":"p3","message":{"role":"user","content":"keep them"}}"#,
    ]))
    #expect(transcript.refresh())
    #expect(transcript.messages.map(\.text) == ["read the store", "/a.ts", "/b.ts", "Both read.", "keep them"])

    // The agent's answer to a rewound prompt, written late, stays out too.
    let late = #"{"parentUuid":"a2","type":"assistant","uuid":"a3","message":{"role":"assistant","content":[{"type":"text","text":"Also gone."}]}}"#
    let handle = try FileHandle(forWritingTo: transcript.url)
    try handle.seekToEnd()
    try handle.write(contentsOf: Data((late + "\n").utf8))
    try handle.close()
    transcript.refresh()
    #expect(transcript.messages.last?.text == "keep them")
}

