    let tool = { (name: String, input: [String: Any]) in ClaudeLog.tool(name, input, in: "/repo", id: "t").text }
    #expect(tool("Read", ["file_path": "/repo/src/app.ts"]) == "src/app.ts")
    #expect(tool("Read", ["file_path": "/elsewhere/notes.md"]) == "/elsewhere/notes.md")
    #expect(tool("Bash", ["command": "git status\ngit diff"]) == "git status")
